import pytest
from globus_cw_client.client import log_event


@pytest.mark.parametrize("message", (object(), {"foo": "bar"}))
def test_log_event_rejects_bad_message_type(message):
    with pytest.raises(TypeError, match="must be bytes or str"):
        log_event(message)


@pytest.mark.parametrize("retries", (object(), "100", 1.5))
def test_log_event_rejects_retries_type(retries):
    with pytest.raises(TypeError, match="retries must be an int"):
        log_event("hi", retries=retries)


def test_log_event_rejects_retries_value():
    with pytest.raises(ValueError, match="retries must be non-negative"):
        log_event("hi", retries=-5)


@pytest.mark.parametrize("wait", (object(), "100"))
def test_log_event_rejects_wait_type(wait):
    with pytest.raises(TypeError, match="wait must be an int or float"):
        log_event("hi", wait=wait)


def test_log_event_rejects_wait_value():
    with pytest.raises(ValueError, match="wait must be non-negative"):
        log_event("hi", wait=-1)

CLIENT_VERSION=$(shell grep 'version=' client/setup.py | grep -Eo '([[:digit:]]|\.)+')
DAEMON_VERSION=$(shell grep 'version=' daemon/setup.py | grep -Eo '([[:digit:]]|\.)+')

.PHONY: help
help:
	@echo "These are our make targets and what they do."
	@echo ""
	@echo "  help:      Show this helptext"
	@echo ""
	@echo "  lint:      run linters and fixers"
	@echo ""
	@echo "  clean:     remove tooling virtualenv"

.venv:
	python3 -m venv .venv
	.venv/bin/pip install pre-commit==1.18.3

.PHONY: lint
lint: .venv
	.venv/bin/pre-commit run --all-files

.PHONY: clean
clean:
	rm -rf .venv

.PHONY: showvars tag-release prepare-release
showvars:
	@echo "VERSION=$(CLIENT_VERSION)"
	@echo "CLIENT_VERSION=$(CLIENT_VERSION)"
	@echo "DAEMON_VERSION=$(DAEMON_VERSION)"
prepare-release:
	tox -e prepare-release
tag-release:
	git tag -s "$(CLIENT_VERSION)" -m "v$(CLIENT_VERSION)"
	-git push $(shell git rev-parse --abbrev-ref @{push} | cut -d '/' -f1) refs/tags/$(CLIENT_VERSION)
